    pdeps.n = 0;
    pdeps.cap = 0;
    nlock = 0;
    lockcap = 0;
    lrows = NULL;
    rc = 0;
    units = 0;
    allcf = 0;
    allcfcap = 0;
    alldf = 0;
    alldfcap = 0;
    qcf = 0;
    qcfcap = 0;
    qlf = 0;
    qlfcap = 0;
