        char * spec;
        spec = pdeps.spec[i];
        if (((_self->__tool_pkg_pkgops_vptr->split_spec(_self, spec, (&dpath), (&drange)) != 0) || (_self->__tool_pkg_pkgops_vptr->dep_name(_self, spec, dname, TEXT_LIMIT) != 0))) {
            fprintf(stderr, "ctc: bad dependency '%s'\n", spec);
            rc = 1;
            continue;
        }
